INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(49000, 0, 490, 0, 0, 0, 'Un''Goro Crater', 'Un''Goro Crater is a vast sunken jungle in southern Kalimdor, ringed by cliffs, with the deserts of Tanaris to the east and the wastes of Silithus beyond its northwestern ridge. Steam rises from its pools, and at its heart the volcano of Fire Plume Ridge still smolders. Visitors say that entering it is like stepping into another world. The crater seems untouched by outside hands, and its creatures are nobler, mightier kin of beasts known elsewhere: devilsaurs and stegodons crash through the trees, ravasaurs hunt the marshes, pterrordax wheel overhead and great apes rule the northeast. Even the plants fight back, for the bloodpetals walk and lash at travelers. Stranger things lie hidden. Colored power crystals glitter across the basin, crystal pylons of legend stand in remote corners, and on the northern bluffs stand a stone terrace and a waygate tied to the titans. In the south the Gorishi silithid have dug a hive, and scholars wonder whether the silithid draw their strength from here. Most visitors shelter at Marshal''s Refuge, a camp of stranded explorers in the north.', 'quest 4294 description (lush, untainted by outside hands, explorers just discovering its secrets); quest 4289 description (nobler versions of creatures, cries of the Earth Mother); quest 4287 reward text (like a completely different world); quest 1124 description (Silithus west of Un''Goro via the northwestern ridge); quest 4493 reward text (Un''Goro west of Gadgetzan; Gracina''s theory); quest 4502 description (volcanic activity in the middle of the crater); quests 4141, 4145 (bloodpetals); quest 3881 description; zone_areas: devilsaur, stegodon, ravasaur, pterrordax, gorilla, Gorishi spawns; power crystal objects; Shaper''s Terrace 4382 and Waygate 4381; warcraft.wiki.gg/wiki/Un''Goro_Crater; warcraft.wiki.gg/wiki/Shaper''s_Terrace (WotLK northern terrace, titan-related, builder not stated)'),
(49001, 1, 490, 1, 0, 0, 'Marshal''s Refuge', 'Marshal''s Refuge is a camp on high ground at the northern edge of the crater, where Marshal Expeditions fled when the beasts overran its base camps. It has become a home for the lost and stranded, where some arrive with a purpose and others by accident. A gnome with no memory lingers among the tents, two travelers who refuse to speak to each other trade pranks, and a castaway named Shizzle, too frightened of gryphons to fly home, builds a flying machine. J.D. Collie studies crystals in a nearby cave, the kodo Dadanga hopes for a snack of bloodpetal sprouts, and Gadgetzan bruisers guard the interests of Gadgetzan. Words written on a stone warn simply: beware of pterrordax.', 'zone_areas area 541: Williden 9270, Hol''anyee 9271, Spark 9272, Petra Grossen 9273, Dadanga 9274, Linken 8737, Larion 9118, Muigin 9119, Spraggle 9997, Shizzle 9998, Quixxil 10977, Gryfe 10583, Gadgetzan Bruiser 9460, Beware of Pterrordax 174682; quest 3884 description (sought higher ground once their base camps were overrun); npc_text 3546 (Spraggle: some come here with a purpose, others by accident); quest 4503 description (Shizzle); quest 3941 description (J.D. in the cave); npc_text 3793, quest 5150 (Dadanga and bloodpetal sprouts); npc_text 9774 (Gadgetzan Bruiser); quest 4501 completion text; warcraft.wiki.gg/wiki/Marshal_Expeditions (Dadanga a kodo); warcraft.wiki.gg/wiki/Dadanga (kodo)'),
(49002, 1, 490, 2, 0, 0, 'Lakkari Tar Pits', 'Just south of Marshal''s Refuge lie the Lakkari Tar Pits, black pools of sticky tar. Creatures of living tar drag themselves out of the muck, from creepers and lurkers to hulking tar lords, while bloodpetal flayers root along the banks and pterrordax circle above. Tran''rek, a schemer in Gadgetzan, wants the tar these beasts carry rather than ordinary pitch, sure that the chlorophyll in their skin makes it uncommonly sticky. Near the pits stands the Northern Crystal Pylon, one of the three great pylons the crater''s few residents whisper about. Here too the engineer Karna Remtravel waits near the refuge, hoping for news of her lost mechanical ape.', 'zone_areas area 538: Tar Beast, Tar Creeper, Tar Lurker, Tar Lord, Bloodpetal Flayer, Thresher, Pterrordax; Northern Crystal Pylon 164955; Karna Remtravel 9618; quest 4504 description and reward text (tar from the beasts, chlorophyll in their skin, super sticky); quest 4285 description (northern pylon fairly close); npc_text 2810 (pylons a source of legend); quest 4243 description; warcraft.wiki.gg/wiki/Lakkari_Tar_Pits (just south of Marshal''s Refuge); warcraft.wiki.gg/wiki/Karna_Remtravel (at the entrance to Marshal''s Refuge)'),
(49003, 1, 490, 3, 0, 0, 'Fungal Rock', 'East of Marshal''s Refuge, Fungal Rock is the lair of the great apes of Un''Goro, where gorillas, stompers and thunderers roam the slopes. The tauren hunter Torwa Pathfinder counts their pelts a fair test of strength, but the greater test waits in a cave at the edge of their land, home of the huge red ape he calls U''cha, in his eyes one of the Earth Mother''s greatest sons, with arms as thick as tree trunks. Here the engineer Karna Remtravel lost her mechanical ape, A-Me 01, after an alpha male rushed up to greet it. The apes seem to have accepted the dented machine: one sleepy thunderer has been seen curling up beside her to snore.', 'quest 4243 description (Fungal Rock, the apes'' lair, just east of here; alpha male); quest 4289 description (great apes to the north); quest 4301 description and completion text (U''cha, cave, huge and red, teeth the size of daggers, arms as thick as tree trunks); creature_text 6516 (thunderer lies down and cuddles up next to A-Me 01); quest 4243 reward text (two dents); zone_areas area 542: Un''Goro Stomper, Gorilla, Thunderer; posarea: U''cha 9622, Uhk''loc 6585 and A-Me 01 9623 stand at the edge of 542 in area 490'),
(49004, 1, 490, 4, 0, 0, 'Fire Plume Ridge', 'Fire Plume Ridge is the smoldering volcano at the heart of the crater, south of Marshal''s Refuge. Living blazes and scorching elementals walk its burned slopes, and the lava lake at its summit is said to be hot enough to fuse thorium and bone. The inventor Krakle had its hot spots measured with a thermometer of his own design, and the readings tied the volcano to the warmth of the Golakka springs. On the ridge dwells Blazerunner, a powerful fire elemental who guards the Golden Flame in a cave there behind an aura no one has broken; many who tried were thrown from the rocky paths. The explorer Ringo wandered here too, and the heat soon left him fainting.', 'zone_areas area 537: Living Blaze 6521, Scorching Elemental 6520, Krakle''s Thermometer 10541 hot spots, Blazerunner 9376, Ringo 9999; quests 5801/5802 description (lava lake up top hot enough to fuse thorium and bone); quest 974 description and reward text; quest 3962 description and log text (Golden Flame in the cave); quest 4005 reward text (charred center, aura, pushed from the rocky paths); quest 4492 description (volcano south of the refuge); quest 4491 description; quest 4502 description'),
(49005, 1, 490, 5, 0, 0, 'Golakka Hot Springs', 'In the west of the crater, steaming pools and geysers make up the Golakka Hot Springs. The inventor Krakle camps on their shore, puzzling over where the heat comes from. He suspects Fire Plume Ridge, though he is too scared of its fire elementals to take the readings himself, and he points the curious to his friend Donova Snowden, who stays by hot springs in Winterspring with no volcano anywhere near them. Pterrordax, diemetradons and stegodons come down to the water, and the Western Crystal Pylon stands nearby. A cheerful woman named Simone strolls these shores with her growling pet Precious, but hunters sent by an ancient of Felwood learn she is an agent of the Burning Legion in disguise.', 'quest 974 description and completion text; quest 980 description (Winterspring springs with no volcano, Donova Snowden); zone_areas area 543: Krakle 10302, Frenzied Pterrordax, Elder Diemetradon, Plated Stegodon, Western Crystal Pylon 164956, Simone the Inconspicuous 14527, Precious 14528; npc_text 7041, 7042 (Simone, Precious); quest 7636 description (Vartrus: demonic corrupters, agents of the Burning Legion); creature_template 14533 Simone the Seductress, 14538 Precious the Devourer; 14528 is type demon; warcraft.wiki.gg/wiki/Golakka_Hot_Springs (western Un''Goro); quest 7636 log text and completion text (Simone the Seductress, disguises); warcraft.wiki.gg/wiki/Simone_the_Inconspicuous'),
(49006, 1, 490, 6, 0, 0, 'Terror Run', 'Terror Run, in the southwest of the crater, earned its name honestly. Herds of stegodons, plated, spiked and thunderstomping, crash among the trees, elder diemetradons bask nearby and frenzied pterrordax wheel overhead, while a great beast called Gruff roams among them. Marshal Expeditions came here to dig for the bones of long-dead stegodons and diemetradons, only to find plenty of living ones as well, and their reluctant chief digger declared the name fantastic, and did not mean it as praise. Dinosaur bones still lie scattered across the ground, and some of the research equipment the expedition left behind when it fled can still be found here. Gorishi reavers and workers stray up from the hive to the east.', 'quest 3882 description (Terror Run, FANTASTIC name, dead and live stegodons and diemetradons); quest 3881 description (supplies left behind); zone_areas area 539: Stegodon, Plated, Spiked, Thunderstomp Stegodon, Elder Diemetradon, Frenzied Pterrordax, Gruff 6583 (rank 2), Dinosaur Bone 161527 x14, Research Equipment 161521, Gorishi Reaver, Worker; warcraft.wiki.gg/wiki/Terror_Run (southwestern Un''Goro, just west of the Slithering Scar); warcraft.wiki.gg/wiki/Gruff (rare stegodon, Terror Run)'),
(49007, 1, 490, 7, 0, 0, 'The Slithering Scar', 'The Slithering Scar is a great silithid hive gouged into the south of the crater, the home of the insects called the Gorishi. Workers, wasps, stingers, tunnelers and reavers swarm through its tunnels, and the ore in its walls comes smeared with ooze. Deep inside lie larval hatcheries hung with dangling spawn, and a brood mother called Clutchmother Zavas prowls the hive. Hol''anyee Marshal finds the Gorishi entirely alien to the ecology of Un''Goro and wants to know why they are here at all. Alchemist Pestlezugg of Gadgetzan believes a crystal in the hatcheries attunes the whole hive, and suspects that the silithid answer to some malign intelligence beyond it.', 'zone_areas area 540: Gorishi Reaver, Worker, Wasp, Tunneler, Stinger, Gorishi Egg, Clutchmother Zavas 6582 (rank 4), Ooze Covered Truesilver Deposit; quest 3883 description (alien to the ecology, larval hatcheries, hanging larval spawns); quest 4507 description and completion text (crystal, hive-wide attunement device, malign intelligence); quest 13903 description (Slithering Scar in the south); warcraft.wiki.gg/wiki/The_Slithering_Scar (Gorishi hive)'),
(49008, 1, 490, 8, 0, 0, 'The Marshlands', 'The Marshlands spread across the southeast of the crater, close to where the road from Tanaris comes down into the jungle. Hunters and runners stalk the reeds, venomhide ravasaurs carry poison in their blood, spit and skin, and their nests lie scattered across the fen under the eye of a fearsome matriarch. Above them all is Lar''korwi, the dominant male whose name means sharp claw. At the southeastern edge of the marsh the trainer Mor''vek raises venomhide hatchlings for riders patient enough to earn one. The Eastern Crystal Pylon stands in these wetlands, and on the shore of a small pond lies a wrecked raft, the first clue to the story of a gnome who lost his memory.', 'zone_areas area 1942: Ravasaur, Ravasaur Hunter, Runner, Venomhide Ravasaur, Ravasaur Matriarch 6581 (rank 4), Venomhide Egg, Ravasaur Matriarch''s Nest, Mor''vek 11701, Eastern Crystal Pylon 164957, A Wrecked Raft 161505, A Small Pack 161504, Un''Goro Flat Rock 169217, Fresh Threshadon Carcass 166863; quest 9063 description (road from Tanaris enters the crater); quest 13850 description (poison blood, spit, skin); quest 4291 description (dominant male); npc_text 2835 (sharp claw); quest 3844 description (wrecked raft by a small pond); warcraft.wiki.gg/wiki/The_Marshlands (southeast, often the first area encountered)'),
(49009, 1, 490, 9, 0, 0, 'The Shaper''s Terrace', 'High on the bluffs above Marshal''s Refuge lies the Shaper''s Terrace, a great expanse of stonework tied to the titans. Beside it stands a titan waygate that joins Un''Goro to Sholazar Basin, far away in Northrend. On the terrace looms the Etymidian, a stone colossus made by the titans, silent and inert, with an empty rune-shaped slot in its chest. It is not alone. Death''s Hand acolytes of the Cult of the Damned have taken the terrace, and their leader, High Cultist Herenn, keeps to the overlook nearby. He knows the colossus is the one being that could stand against the armies of the Scourge, and he is determined that it never reach Northrend.', 'zone_areas area 4382: Death''s Hand Acolyte 28602 x10, The Etymidian 28092; area 4381 Waygate; quest 12546 description (one of the most destructive forces ever created by the titans); quest 12548 description (Waygate activated for the first time in seven centuries); quest 12561 description (Sholazar, the cradle of life); quest 12547 description (rune-shaped slot, Omega Rune inside the Shaper''s Terrace); creature_text 28601 (High Cultist Herenn); warcraft.wiki.gg/wiki/Shaper''s_Terrace (added in 3.0.2, on the bluffs above Marshal''s Refuge, Cult of the Damned, Herenn holds the Omega Rune); quest 12547 description (inactive colossus, empty rune-shaped slot, nearby overlook); creature_text 28601 (Herenn)'),
(49010, 2, 490, 1, 0, 0, 'Linken', 'Linken is a gnome who turned up in Un''Goro with no idea how he got there. He remembers traveling, and a raft, and little else. The refugees find him friendly and a little strange: unlike most gnomes he shows no interest in gadgets, and he sometimes greets people with a demand for payment before catching himself. Asked how he came to the crater, he can only say that it is a secret to everybody. In truth he is a warrior on the last step of a long journey, come to defeat the fire elemental Blazerunner and take the Golden Flame back to his homeland. Whoever restores his memory and his sword earns the title he bestows: hero of Un''Goro Crater.', 'npc_text 2633 (not sure how I got here, a raft); npc_text 2634 (Pay me and I''ll talk); npc_text 2635 (hero of Ungoro Crater); quest 3908 description (it''s a secret to everybody); quest 3961 description (not interested in experiments or gadgets like most gnomes; a true warrior at heart); quest 3962 description and reward text (journey, last step, Golden Flame returned to my homeland); warcraft.wiki.gg/wiki/Linken (gnome warrior, raft crash)'),
(49011, 2, 490, 2, 0, 0, 'J.D. Collie', 'J.D. Collie is a gnome who has made a cave at Marshal''s Refuge her home, though she cannot say how she came to the crater. She spends her days on the colored power crystals that lie all over Un''Goro, certain they hold a power everyone else ignores. Her experiments rarely go to plan. Many end in a yelp of pain and a promise that the last thirteen tries were only practice, and now and then she wonders aloud whether she should go back downstream. She admits she will believe almost anything she is told, including tales of great crystal pylons in the wilds. She was kind to Linken when he first stumbled in, and remembers what he mumbled.', 'npc_text 2817 (cave is my home now, can''t say how I got here, studies crystals); creature_text 9117 (OW, last 13 tries were just practice, go back downstream); quest 4284 description; quest 4285 description (call me gullible, I''ll usually believe anything); quest 3941 description (J.D. was very kind to me when I first arrived); quest 3942 description; warcraft.wiki.gg/wiki/J.D._Collie (female gnome); creature_template_model 9117 display 8478, creature_model_info Gender 1'),
(49012, 2, 490, 3, 0, 0, 'Williden and Hol''anyee Marshal', 'Williden Marshal and his sister Hol''anyee lead Marshal Expeditions, a troupe of scientists and explorers aligned with no faction who travel Azeroth in search of its wild and untamed majesty. Williden is the leader, still able to welcome a stranger warmly in the middle of disaster. Hol''anyee is the chief scientist and biologist, who holds that a setback is no reason for research to stop. Un''Goro was meant to be their greatest venture, and it has become their worst. They underestimated the savagery of the crater, lost their camps and most of what they brought, and now wait out their troubles at the refuge, while their chief digger offers his gold teeth to anyone who will carry him away.', 'npc_text 3096 (Williden: my sister, our companions, scientists and explorers); npc_text 3095 (Hol''anyee: chief scientist and biologist, my brother); quest 3881 description (non-aligned expedition troupe, latest and greatest endeavor, underestimated the savagery); quest 3883 description (setback does not stop research); quest 3884 reward text (lost like almost everything else); npc_text 3094 (Spark: gold teeth); warcraft.wiki.gg/wiki/Marshal_Expeditions'),
(49013, 2, 490, 4, 0, 0, 'Torwa Pathfinder', 'Torwa Pathfinder is a tauren hunter who camps where the road from Tanaris enters the crater. To him Un''Goro cries of the Earth Mother: its creatures seem nobler versions of the beasts of his homeland, and he thanks the spirits of every one that falls. He measures others not by race or calling but by the testing of spirit and mind against nature, and he respects any who can stand against the crater''s great beasts. The ravasaur Lar''korwi killed his brother not far from his camp. Torwa has also sought druids for a gentler purpose, a toxin of bloodcap, Gorishi stings and Un''Goro soil to calm the devilsaurs, since killing one only lets another take its territory.', 'npc_text 2816 (race and profession mean nothing, testing of spirit and mind); quest 4289 description and reward text (cries of the Earth Mother, nobler versions, thank the spirits); quest 9063 description (requested the help of a druid; road from Tanaris); quests 9052, 9051, 9053 (bloodcap, Gorishi stings, Un''Goro soil; pacify the devilsaurs; another moves into its territory); quest 4290 description (brother killed not far from this spot); warcraft.wiki.gg/wiki/Torwa_Pathfinder (tauren hunter)'),
(49014, 2, 490, 5, 0, 0, 'Karna Remtravel', 'Karna Remtravel is a dwarf engineer camped near Marshal''s Refuge who finds the crater simply amazing, though not quite as amazing as the things she can build. Like her uncle Remtravel, who loves old places, she dreams of discovering new things from lost cultures. To study the apes up close she built a mechanical ape, A-Me 01, with scrying gems for eyes so that Karna could see all she saw. A-Me reached Fungal Rock before the link failed, the last image an alpha male rushing up to say hello. When she was found, A-Me was dented and her mithril casing burnt out, but a new casing brought her back, and she picked her way home murmuring that A-Me is good.', 'npc_text 2734 (amazing, engineering, uncle Remtravel loves old stuff, lost cultures); quest 4243 description and reward text; quest 4244 description and reward text (mithril casing burnt out); creature_text 9623 (A-Me good, home); quest 4245 reward text; npc_text 2735; warcraft.wiki.gg/wiki/Karna_Remtravel (dwarf, female, uncle Remtravel); creature_template_model 9618 display 8831, creature_model_info Gender 1; warcraft.wiki.gg/wiki/Karna_Remtravel'),
(49015, 2, 490, 6, 0, 0, 'Spraggle Frock and Ringo', 'Spraggle Frock greets newcomers to Marshal''s Refuge with the thought that some arrive with a purpose and some by accident, but everyone there has a story. Hers is one of fright. She never worried about the crater''s beasts until she found the words ''beware of pterrordax'' written on a large stone, and now she will not leave the refuge until someone thins their numbers. Her friend Ringo is bolder, or less careful. He went to explore the volcano to the south and stayed far too long, until the heat left him faint on the slopes of Fire Plume Ridge. Spraggle sent her canteen with whoever would look for him, for a splash of water brings him round.', 'npc_text 3546 (Spraggle gossip); quest 4501 completion and reward text; quest 4492 description; quest 4491 description; creature_text 9999 and 9997; warcraft.wiki.gg/wiki/Spraggle_Frock (female); warcraft.wiki.gg/wiki/Spraggle_Frock (female goblin)'),
(49016, 2, 490, 7, 2, 0, 'Mor''vek', 'Mor''vek is a ravasaur trainer who keeps a camp in the southeast of the Marshlands and raises the venomhide ravasaurs of Un''Goro as mounts. It is not a trade for the impatient. Venomhides are poison through and through, in blood, spit and skin, and anyone who climbs onto one unprepared falls off dead within hours. Mor''vek sells a hatchling only to one who has built up a tolerance by being splashed with their poisoned blood again and again, and who can then find the rare light-shelled eggs in the marsh nests, which grow fewer with every clutch. The hatchling must be hand-fed until it sheds its baby teeth. Few have that dedication, he says, but the venomhides are worth it.', 'quest 13850 description and reward text; quest 13887 description and reward text (lighter colored shells; fewer with each clutch); quest 13906 description and reward text (baby teeth, few have the dedication); npc_text 14474; quests 13889, 13903, 13904, 13905 (hatchling feeding); creature_template 11701 subname Ravasaur Trainers, faction 126; factiontemplate_dbc 126'),
(49017, 2, 490, 8, 0, 0, 'Blazerunner', 'Blazerunner is the fire elemental who dwells on Fire Plume Ridge in the charred center of the crater. To Eridan Bluewind of the Emerald Circle he is evil in its purest form. He guards the Golden Flame, an artifact of vast power kept in a cave there, and with it he has raised an aura that no one has been able to penetrate. The residents of Marshal''s Refuge keep their distance, for many who tried to face him were pushed from the rocky paths to the ground below. Only a totem shaped by the summoned elemental Aquementas can strip that protection away, and it was to face Blazerunner that the gnome Linken made his long journey.', 'quest 4084 description (evil of the purest form, aura none can dispel); quest 4005 description and reward text (charred center, aura, pushed from the rocky paths; totem to fight Blazerunner); quest 3962 description and completion text (guards the Golden Flame, aura created using it); quest 3961 description; DB: 9376 faction 91, rank 1, area 537; factiontemplate_dbc 91'),
(49018, 3, 490, 1, 0, 0, 'It''s a Secret to Everybody', 'On the shore of a small pond in the Marshlands lies a wrecked raft, though the pond seems far too small to have carried it. In the water lies a sodden pack, and its contents lead to Marshal''s Refuge and to Linken, a gnome who finds them familiar, kind of. One memory stirs: his sword was to be strengthened. He sends it to Donova Snowden at the hot springs of Winterspring, who tempers it and learns with alarm that Linken has lost his memory. Finishing the blade needs help from one the living cannot see. Gregan Brewspewer of Feralas brews a Videre Elixir from evoroot, and whoever drinks it at the graveyard outside Gadgetzan walks in spirit due north to the ghost Gaeriyan, who waits in a rocky crevice of the mountains. He tells of a gravestone that slides aside to reveal a hollow shaped for the sword. Laid there, the blade is transformed in a flash of light. Linken is delighted to have it back, though he still cannot remember why he needed it.', 'quests 3844, 3845, 3908, 3909, 4041, 3912, 3913, 3914 (descriptions, request and reward texts); feralas.json 35714 (Miblon guards the evoroot) and 35713 (Gregan, no triggers)'),
(49019, 3, 490, 2, 0, 0, 'The Golden Flame', 'Still unable to recall why he came, Linken sends a helper to J.D. Collie in her cave, hoping he let something slip when he first arrived. He did: he had mumbled of making a totem and of a druid named Eridan Bluewind in Felwood. Eridan does not know him, but she knows what he sought. In the heart of Un''Goro, the fire elemental Blazerunner hides behind an aura none can dispel. For silvery claws and the heart of an irontree, she gives over the Book of Aquor, to be read from a circle of stones on the eastern point of Lost Rigger Cove in Tanaris. The elemental Aquementas is not pleased to be woken, but within the circle it forges the Silver Totem of Aquementas. The totem brings back the last of Linken''s memory. This was to be the final step of his journey, yet he declares that the hero now is the one who helped him, and warns that it is dangerous to go alone. With Blazerunner fallen, the Golden Flame goes home to Linken''s land to be guarded.', 'quests 3941, 3942, 4084, 4005, 3961, 3962 (descriptions, completion and reward texts); felwood.json 36119 (Eridan Bluewind, Un''Goro quests mentioned without triggers)'),
(49020, 3, 490, 3, 0, 0, 'Marshal Expeditions', 'Marshal Expeditions came to Un''Goro on what was meant to be its greatest venture and met disaster after disaster. The crater''s beasts overran its base camps in the southwest and the northeast, and the troupe fled for higher ground, leaving behind its food, its research equipment and even Williden Marshal''s journal, later found mangled in the wilds. At the refuge, the expedition clings to its purpose. Williden needs the crate of foodstuffs and some of the equipment recovered if anyone is to survive. His sister Hol''anyee wants a scraping from the walls of the Gorishi hatcheries, to learn why the silithid are in the crater at all. Spark Nilminer, the reluctant chief digger, is meant to bring back bones of long-dead stegodons and diemetradons from Terror Run. Privately he admits that bones from living ones will do just as well, and asks that no one mention it. Meanwhile the kodo Dadanga waits hopefully for a meal of bloodpetal sprouts.', 'quests 3881, 3882, 3883, 3884 (descriptions, completion and reward texts); quest 5150 texts, npc_text 3793 (Dadanga); npc_text 3094'),
(49021, 3, 490, 4, 0, 0, 'Crystals of Power', 'Power crystals of red, blue, yellow and green lie all over the crater, and most people ignore them. J.D. Collie does not. Certain they hold power, she experiments endlessly in her cave at Marshal''s Refuge and sends out collectors when her supply runs low. She has also heard rumors of mysterious pylons standing in the wilds, large and lined with crystals inside, and she is sure the stories are true. Searchers find all three: the northern pylon by the tar pits, the eastern in the Marshlands and the western near the Golakka springs. To the crater''s few residents they are a mystery and a source of legend. From what is learned, J.D. works out how each pylon fuses two colors into one charm. One heals, one steadies the spirit, one hardens the body against blows, one weakens a foe''s defenses, one bursts in a stunning blast and one raises a shield that strikes back at attackers. She sets it all down in a manual for those who would use them.', 'quests 4284, 4285, 4287, 4288, 4321 (descriptions and reward texts); quests 4381-4386 completion texts; npc_text 2810, 2834, 2836, 2837, 2933; zone_areas: pylons 164955 (538), 164957 (1942), 164956 (543)'),
(49022, 3, 490, 5, 0, 0, 'Torwa''s Trials', 'Torwa Pathfinder grants his respect only to those who prove themselves against the crater''s greatest beasts. The first test lies north among the great apes, whose pelts will clothe his tribe; after it he speaks of U''cha, a huge red ape in their cave and one of the Earth Mother''s greatest sons. The hardest test is Lar''korwi, dominant male of the ravasaurs, whose name means sharp claw. Long ago Torwa''s brother took meat from one of its kills. The beast followed him for days, and when he fled the crater it killed him not far from Torwa''s camp. To draw Lar''korwi out, a hunter must repeat the offense, stealing meat from its freshest kill, an oddly placed threshadon, and then the scent glands of its mates from beside their eggs. Laid together on a trail in the hills, among the bones of massive creatures, the two lures bring the beast into the open. Its head earns Torwa''s highest praise.', 'quests 4289, 4301, 4290, 4291, 4292 (descriptions, completion and reward texts); npc_text 2835 (taurahe, sharp claw)'),
(49023, 3, 490, 6, 0, 0, 'The Gorishi Hive Queen', 'Gracina Spiritmight in Darnassus and Zilzibin Drumlore in Orgrimmar came to the same suspicion: the silithid draw their strength from Un''Goro Crater. Alchemist Pestlezugg of Gadgetzan, who had already studied the bugs of Tanaris, thought it worth finding out. His research told him the silithid are like bees, and that killing a hive''s queen should throw the rest into disarray. He brewed a lure from Un''Goro soil and an undamaged scent gland taken from the Gorishi of the Slithering Scar. Inside the hatcheries waits a crystal the insects seem to use to attune the whole hive, and the lure set upon it brings the Gorishi Hive Queen out among her guards. Pestlezugg wanted her brain, for he had come to believe the silithid answer to a malign intelligence. Even in victory he was uneasy, warning that so clean an end could not be the full extent of their presence. Word of the hunt went back to the scholars who had first sent for help.', 'quests 4493, 4494 descriptions and reward texts (Gracina, Zilzibin); quest 4496 description, completion and reward text; quest 4507 description, completion and reward text; quests 4510, 4511 descriptions (assumption wrong, far stronger presence); tanaris.json 44030 (Pestlezugg''s earlier study)'),
(49024, 3, 490, 7, 0, 0, 'The Bloodpetal Feud', 'Larion and Muigin set out together and ended up lost in Un''Goro, and each blames the other. Larion says he knew the way until Muigin insisted on a shortcut; Muigin says he warned Larion they were going the wrong way. Now they camp a few steps apart at Marshal''s Refuge, neither willing to speak first. Muigin has turned to mischief. Convinced the bloodpetals have a scrap of intelligence, he sent one to his friend Gregan Brewspewer, an herbalist who left Ironforge for the quiet of the Feralas wilds, and on Gregan''s advice he tamed the sprouts with Atal''ai haze from the sunken temple in the Swamp of Sorrows. The pests now plague Larion night and day. Larion fights back. His friend Marvon Rivetseeker of Ratchet was away among the troll ruins of Tanaris, but Marvon''s apprentice had built a bug zapper that runs on the same haze. Muigin admits he knows the way home, but he will not leave until Larion says he was right.', 'quests 4141, 4142, 4143, 4144 (Muigin, Alliance) and 4145, 4147, 4146, 4148 (Larion, Horde): descriptions, completion and reward texts; quest 4502 description (Liv, apprentice to Marvon); npc_text 6741 (Larion: pests night and day); creature_text 9119');
